import './Veiculo.css';
import carros from './carros';
import { useParams } from 'react-router-dom';


function Veiculo(props) {
    const { id } = useParams();
    const carro = carros.find((item) => item.id === parseInt(id));

    if (!carro) {
    return <h2>Carro não encontrado!</h2>;
  }

  return(
            <div className="col"> 
            <div className="card shadow-sm"> 
                <img
                    src={carro.img}
                    className= "bd-placeholder-img card-img-top" 
                    alt={props.titulo}
                    width="100%" 
                    height="300"
                />    
                <div className="card-body">                

                         <p className="propriedades-veiculo"><b>{props.titulo}</b></p> 
                         <p className="propriedades-veiculo"><b>R${props.preco}</b></p>
                    </div> 
                 </div> 
            </div>
  );
}

export default Veiculo;
